async function startRecording(){if(!window.MediaRecorder)throw Error('이 브라우저는 기준영상 녹화를 지원하지 않습니다.');recordCanvas=document.createElement('canvas');recordCanvas.width=$('video').videoWidth;recordCanvas.height=$('video').videoHeight+80;mediaStream=recordCanvas.captureStream(30);const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('지원되는 영상 녹화 형식이 없습니다.');media=new MediaRecorder(mediaStream,{mimeType:mime});media.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};media.onerror=()=>{if(running)stop('기준영상 녹화 오류로 세션을 종료했습니다.');};media.start(1000);recordStarted=elapsed();session.data.video={mime,startedAtSessionSeconds:recordStarted,frameRateRequested:30,width:recordCanvas.width,height:recordCanvas.height};session.event('VIDEO_START',recordStarted);}
