function drawStage(){if(!stage)return;if(stage.kind==='gazeMark'){ $('capturePoint').hidden=true;$('nextTrial').hidden=true;$('targetDot').hidden=true;$('outsideInstruction').hidden=true;txt('stimulusTitle','내 시선 위치 표시 테스트');txt('stimulusDetail','청록색 원은 눈에서 추정한 위치입니다. 머리를 고정하고 화면 여러 곳을 바라보세요.');txt('stimulusProgress',session.data.meta.mode==='demo'?'DEMO · 실제 눈 측정이 아닌 합성 좌표':'웹캠 시선 추정 · 닫기 / Esc로 종료');return;}const cal=stage.kind==='calibration';$('capturePoint').hidden=true;$('nextTrial').hidden=true;$('capturePoint').disabled=!!capture;$('targetDot').hidden=!cal&&!['target','screenInside'].includes(stage.kind);$('outsideInstruction').hidden=cal||['target','screenInside'].includes(stage.kind);txt('stimulusTitle',cal?'9점 화면 보정 · 머리를 고정하고 표적을 바라보세요':stage.kind==='screenInside'?'화면 안 주시 · 점을 바라보세요':stage.kind==='screenOutside'?'화면 밖 주시 · 머리를 고정하고 눈만 움직이세요':stage.kind==='target'?'시선 방향 검증 · 표적을 바라보세요':stage.kind==='outside'?'화면 바깥 실제 표적을 바라보세요':'머리 방향 검증 · 해당 방향으로 고개를 움직이세요');txt('stimulusDetail',cal?'점만 바라보세요. 눈과 머리가 안정되면 자동 수집하고 다음 점으로 이동합니다. 측정 시간에는 포함하지 않습니다.':'버튼을 누르지 마세요. 정해진 시간이 지나면 다음 회차로 자동 이동합니다.');
if(cal||['target','screenInside'].includes(stage.kind)){const [x,y]=cal?CAL_POINTS[stage.index]:stage.items[stage.index].point;$('targetDot').style.left=x*100+'%';$('targetDot').style.top=y*100+'%';}else txt('outsideInstruction',stage.items[stage.index].text);txt('stimulusProgress',cal?'측정 전 보정 · 수집 '+calPoints.length+' / 9 · 현재 '+(stage.index+1)+'번':(stage.index+1)+' / '+stage.items.length);txt('capturePoint',capture?'수집 중…':'이 표적 수집 · Space');}

function collectPoint(raw,t){if(stage?.kind!=='calibration')return;if(!capture)capture={start:t,samples:[]};const result=automaticCalibrationStep(capture,raw,t);if(result.status==='collecting'){txt('stimulusProgress','자동 보정 '+(stage.index+1)+' / 9 · '+Math.min(100,Math.round((t-capture.start)/AUTO_CALIBRATION.duration*100))+'%');return;}if(result.status==='collecting')return;capture=null;if(result.status==='retry'){stage.retries=(stage.retries??0)+1;if(stage.retries>=3){closeStage();txt('calStatus','자동 보정 미완료 · 얼굴·눈·조명을 확인하고 다시 보정하세요.');notice('안정된 눈 관측을 충분히 얻지 못했습니다. 카메라 위치를 확인한 뒤 9점 보정을 다시 시작하세요.',true);return;}capture={start:t,samples:[]};txt('stimulusDetail',result.reason+' 자동 재시도 '+stage.retries+' / 3');return;}const list=result.samples;const median=values=>values.sort((a,b)=>a-b)[Math.floor(values.length/2)];const point={x:CAL_POINTS[stage.index][0],y:CAL_POINTS[stage.index][1],irisX:median(list.map(s=>s.irisX)),irisY:median(list.map(s=>s.irisY)),openEar:result.openEar,pose:Object.fromEntries(['yaw','pitch','roll'].map(k=>[k,median(list.map(s=>s.pose[k]))]))};stage.retries=0;calPoints.push(point);session.event('POINT_CAPTURED',t,{point:stage.index+1,frames:list.length,method:'automatic_stable_observation'});stage.index++;if(stage.index<9){drawStage();return;}try{const model=fitScreen(calPoints);session.data.config.ear=Math.max(.04,calPoints[0].openEar*.65);prepareCalibration(session,{model,neutral:calPoints[0].pose,points:calPoints,coordinateSpace:session.data.meta.calibrationCoordinateSpace,fittedAt:t,collectionMethod:'automatic_stable_observation',collectionRule:{...AUTO_CALIBRATION},openEar:calPoints[0].openEar},t);txt('calStatus',(session.data.meta.viewport.fullscreen?'전체 화면':'브라우저 표시 영역')+' 자동 보정 완료 · 10회 테스트를 선택하세요');closeStage(false);txt('sessionStatus','보정 완료 · 아직 측정 전');notice('자동 보정 완료 · 화면 안 또는 화면 밖 10회 테스트를 선택하세요. 선택한 테스트만 자동 측정합니다.');render(t);$('insideTest').scrollIntoView({block:'center',behavior:'smooth'});}catch(e){closeStage();calPoints=[];txt('calStatus','보정 실패 · '+e.message);notice('보정점의 눈 이동이 일관되지 않아 보정을 완료하지 못했습니다. 각 점을 바라보며 다시 진행하세요.',true);}}
async function beginGazeMark(){if(!running||!session.calibration||session.task||stage)return;if(!measuring)await beginMeasurement();if(!measuring)return;stage={kind:'gazeMark'};session.event('GAZE_MARK_START',elapsed());$('stimulus').hidden=false;drawStage();}
function renderGazeMark(t){const s=session.data.samples.at(-1),m=markerPosition(s,t,session.data.config.hold);$('gazeMarker').hidden=!m.visible;if(m.visible){$('gazeMarker').style.left=m.x*100+'%';$('gazeMarker').style.top=m.y*100+'%';}txt('gazeMarkerStatus',m.status==='lost'?'시선 관측 없음 · 표시 대기':m.status==='outside'?'표시 영역 밖으로 추정 · 원 숨김':'추정 좌표 x='+m.x.toFixed(3)+' / y='+m.y.toFixed(3));$('gazeMarkerStatus').hidden=false;}
async function beginTrial(kind){if(!running||!session.calibration||session.task||stage)return;if(!measuring)await beginMeasurement();if(!measuring)return;if(session.data.meta.mode==='camera'&&(innerWidth!==session.data.meta.viewport.width||innerHeight!==session.data.meta.viewport.height))return notice('보정 당시 창 크기로 되돌리거나 새 세션에서 다시 보정하세요.',true);
const targets=[[.5,.5],[.2,.5],[.8,.8],[.5,.2],[.2,.2],[.8,.5],[.2,.8],[.8,.2],[.5,.8]];
const items=kind==='screenInside'?Array.from({length:10},(_,i)=>({screen:'INSIDE',point:targets[i%targets.length],text:'화면 안의 점'})):kind==='screenOutside'?Array.from({length:10},(_,i)=>({screen:'OUTSIDE',code:['LEFT','RIGHT','UP','DOWN'][i%4],text:'화면 밖 '+label(['LEFT','RIGHT','UP','DOWN'][i%4])+' 표적을 바라보세요'})):kind==='target'?targets.map(point=>({point,text:'화면 내 표적'})):kind==='outside'?['LEFT','RIGHT','UP','DOWN'].map(code=>({code,text:'화면 밖 '+label(code)+' 표적'})):['CENTER','LEFT','RIGHT','UP','DOWN','TILT_LEFT','TILT_RIGHT'].map(code=>({code,text:'머리 '+label(code)}));
stage={kind,items,index:0,start:elapsed(),runId:'RUN'+(session.data.events.length+1)};session.event('TRIAL_RUN_START',stage.start,{runId:stage.runId,kind,planned:items.length});$('stimulus').hidden=false;startTrial();drawStage();}
function startTrial(){const item=stage.items[stage.index];const trial={id:'S'+(session.data.trials.length+1),kind:stage.kind,runId:stage.runId,targetRule:['target','screenInside'].includes(stage.kind)?{...TARGET_RULE}:undefined,screenRule:['screenInside','screenOutside'].includes(stage.kind)?{...SCREEN_RULE}:undefined,instruction:item,start:elapsed(),end:null,referenceConfirmed:false};session.data.trials.push(trial);stage.trial=trial;session.activeTrialId=trial.id;session.event('TRIAL_START',trial.start,{trialId:trial.id,instruction:item});}
function updateTrial(t){const left=Math.max(0,session.data.meta.trialSeconds-(t-stage.trial.start));txt('stimulusProgress',(stage.index+1)+' / '+stage.items.length+' · '+left.toFixed(1)+'s');$('nextTrial').disabled=left>0;txt('nextTrial',stage.index===stage.items.length-1?'지시 종료':'다음 지시');if(left===0)nextTrial();}
function nextTrial(){if(!stage||stage.kind==='calibration'||$('nextTrial').disabled)return;stage.trial.end=Math.min(elapsed(),stage.trial.start+session.data.meta.trialSeconds);session.event('TRIAL_END',stage.trial.end,{trialId:stage.trial.id});stage.index++;if(stage.index===stage.items.length){const autoSave=['screenInside','screenOutside'].includes(stage.kind);closeStage(false);if(autoSave)stop('10회 주시 테스트를 마쳐 결과를 저장했습니다.');else notice('자동 지시를 마쳤습니다. 측정을 종료하면 결과를 확인할 수 있습니다.');return;}startTrial();drawStage();}
function closeStage(interrupted=true){if(stage?.kind==='gazeMark')session.event('GAZE_MARK_END',elapsed());$('gazeMarker').hidden=true;$('gazeMarkerStatus').hidden=true;if(interrupted&&stage?.trial&&!stage.trial.end){stage.trial.end=elapsed();stage.trial.interrupted=true;session.event('TRIAL_INTERRUPTED',elapsed(),{trialId:stage.trial.id});}stage=null;capture=null;if(session)session.activeTrialId=null;$('stimulus').hidden=true;}
async function beginMeasurement(){if(!running||measuring||loading||stage)return;const prepared=session,preparationSeconds=elapsed();loading=true;controls();try{session=beginMeasurementSession(prepared,preparationSeconds);startAt=performance.now();lastRender=0;recordFrame=0;measuring=true;if(session.data.meta.recordVideo)await startRecording();loading=false;txt('sessionStatus','● '+session.data.meta.session+' · 측정 기록 중');txt('liveBadge',session.data.meta.mode==='demo'?'DEMO · 측정 중':'LIVE · 측정 중');controls();notice('측정 시작 · 0초부터 연구 자료를 기록합니다. 표적 테스트 또는 문항을 시작하세요.');}catch(e){mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;media=null;measuring=false;session=prepared;startAt=performance.now()-preparationSeconds*1000;loading=false;controls();notice('측정 시작 실패: '+e.message,true);}}
async function stop(reason='측정을 종료하고 기록을 저장했습니다.'){if(!running)return;const wasMeasuring=measuring,t=elapsed();running=false;loading=true;cancelAnimationFrame(raf);closeStage();measuring=false;let savedVideo=false;if(wasMeasuring){selected=session.finish(t);session.event('SESSION_END',selected.duration);}if(media&&media.state!=='inactive'){await new Promise(resolve=>{media.addEventListener('stop',resolve,{once:true});media.stop();});if(wasMeasuring){const blob=new Blob(chunks,{type:media.mimeType});videoBlobs.set(selected.meta.session,blob);selected.video.frameCount=recordFrame;selected.video.endedAtSessionSeconds=selected.duration;savedVideo=true;}}mediaStream?.getTracks().forEach(t=>t.stop());media=null;mediaStream=null;stream?.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;if(wasMeasuring){history.unshift(selected);save();}loading=false;$('demoControls').hidden=true;$('emptyCamera').hidden=false;txt('sessionStatus',wasMeasuring?'✓ 측정 종료':'카메라 연결 종료 · 측정 전');txt('liveBadge','STANDBY');controls();if(wasMeasuring){show('review');notice(reason+(savedVideo?' 기준영상을 페이지 종료 전에 다운로드하세요.':'')+(storageFailed?' 저장 실패 · JSON을 다운로드하세요.':''));}else notice('보정 준비를 종료했습니다. 측정을 시작하지 않아 연구 기록과 영상은 저장하지 않았습니다.');}
$('start').onclick=start;$('measureStart').onclick=beginMeasurement;$('stop').onclick=()=>stop();$('calibrate').onclick=beginCalibration;$('closeStimulus').onclick=()=>{if(measuring&&['screenInside','screenOutside','gazeMark'].includes(stage?.kind))stop('테스트를 중단하고 완료된 구간까지 저장했습니다.');else closeStage();};$('nextTrial').onclick=nextTrial;$('targetTest').onclick=()=>beginTrial('target');$('insideTest').onclick=()=>beginTrial('screenInside');$('outsideTest').onclick=()=>beginTrial('screenOutside');$('headTest').onclick=()=>beginTrial('head');$('gazeMarkTest').onclick=beginGazeMark;
$('taskStart').onclick=()=>{if(!measuring||!session.calibration)return;try{session.startTask(elapsed(),{itemId:$('itemId').value,itemLabel:$('itemLabel').value});renderLiveItem(elapsed());controls();}catch(e){notice(e.message,true);}};
$('taskResponse').onclick=()=>{if(running){session.respond(elapsed());renderLiveItem(elapsed());controls();}};
$('taskDelay').onclick=()=>{if(running){session.toggleDelay(elapsed());renderLiveItem(elapsed());controls();}};
$('taskEnd').onclick=()=>{if(running){session.endTask(elapsed());const next=session.data.tasks.length+1;$('itemId').value='Q'+String(next).padStart(2,'0');$('itemLabel').value='모의 문항 '+next;renderLiveItem(elapsed());controls();}};
$('mark').onclick=()=>{if(measuring)session.event('MARKER',elapsed());};
function renderLiveItem(t){const k=session?.task;if(!k){txt('liveItemInfo',measuring?'문항을 제시하면서 문항 시작을 누르세요. 끝나면 다음 문항 ID가 준비됩니다.':'9점 보정 → 측정 시작 후 문항을 시작하세요.');return;}const delays=session.data.timings.filter(e=>e.taskId===k.id&&e.kind==='DELAY'),total=delays.reduce((s,e)=>s+e.duration,0)+(session.delay!==null?t-session.delay:0);txt('liveItemInfo',k.itemId+' · '+k.itemLabel+' | 진행 '+fmt(t-k.start,3)+'초 | 첫 반응 '+(k.response===null?'대기':fmt(k.response-k.start,3)+'초')+' | 지연 '+fmt(total,3)+'초'+(session.delay!==null?' (지연 기록 중)':''));}

document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Escape'){$('closeStimulus').click();return;}if(e.code==='Space'){if(stage?.kind==='calibration'){e.preventDefault();return;}else if(running&&session.task){e.preventDefault();session.respond(elapsed());controls();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)stop('탭이 숨겨져 측정을 종료했습니다.');});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(running&&session.calibration&&(innerWidth!==session.data.meta.viewport.width||innerHeight!==session.data.meta.viewport.height))stop('화면 크기가 바뀌어 보정 좌표가 달라졌습니다. 새 세션으로 시작하세요.');},200);});
window.addEventListener('beforeunload',e=>{if(running||loading||[...videoBlobs.keys()].some(id=>!history.find(s=>s.meta.session===id)?.video?.downloaded)){e.preventDefault();e.returnValue='';}});
function refreshHistory(){const list=registry?.selectedId?history.filter(s=>s.meta.participant===registry.selectedId):history;$('history').replaceChildren();if(!list.length){$('history').add(new Option('이 대상자의 기록 없음',''));$('reviewEmpty').hidden=false;$('reviewContent').hidden=true;for(const id of ['exportFull','exportA','exportTimingA','exportBins','exportRaw','downloadVideo'])$(id).disabled=true;return;}list.forEach(s=>$('history').add(new Option(new Date(s.startedAt).toLocaleString('ko-KR')+' · '+modeName(s.meta.mode)+' · '+s.meta.session,s.meta.session)));const data=list.includes(selected)?selected:list[0];$('history').value=data.meta.session;renderReview(data);}
function tr(id,values){let row=document.createElement('tr');values.forEach(v=>{let cell=document.createElement('td');cell.textContent=v;row.append(cell);});$(id).append(row);}
function stat(id,title,value,detail){let box=document.createElement('div');box.className='card stat';let a=document.createElement('small'),b=document.createElement('b'),p=document.createElement('p');a.textContent=title;b.textContent=value;p.textContent=detail;box.append(a,b,p);$(id).append(box);}
const metricNames={direction:'시선 방향',screen:'화면 상태',head:'머리 방향'},timeNames={GAZE:'주시 지속시간',RESPONSE:'반응시간',DELAY:'지연시간'};
const modeName=m=>({demo:'DEMO · 합성자료',camera:'웹캠',reference:'A 전용'})[m]||m;
const groupName=g=>modeName(g.mode)+' / '+(g.role==='validation'?'재검증':'개발');
function renderReview(data){if(!data)return;selected=data;data.references??={};$('reviewEmpty').hidden=true;$('reviewContent').hidden=false;
for(const id of ['exportFull','exportA','exportTimingA'])$(id).disabled=false;for(const id of ['exportBins','exportRaw'])$(id).disabled=!!data.referenceOnly;
$('downloadVideo').disabled=!videoBlobs.has(data.meta.session);$('detailedResults').open=!!data.referenceOnly;$('referenceSetup').hidden=true;$('raterLink').hidden=!data.referenceOnly;
const a=summarizeRaterA(data),p=summarizeProgram(data),grid=referenceBins(data);renderAutomatic(data,p);$('programDetails').open=false;$('aSummary').open=!!data.referenceOnly;
txt('resultMeta',modeName(data.meta.mode)+' | '+data.meta.participant+' | '+data.meta.session+' | 전체 '+fmt(data.duration,3)+'초 · 구간요약 '+fmt(a.totalSeconds,3)+'초 / '+a.totalBins+'개'+(storageFailed?' | 저장 실패':''));
$('metricCards').replaceChildren();$('metricRows').replaceChildren();a.fields.forEach(f=>{stat('metricCards',metricNames[f.field]+' · A 유효 판독',f.valid+' / '+f.total+' 구간','유효 '+fmt(f.valid*.5)+'초 · 미입력 '+f.missing+' · 판단 불가 '+f.unclear);f.categories.forEach(c=>tr('metricRows',[metricNames[f.field],label(c.category),c.n,fmt(c.seconds),fmt(c.totalPct),fmt(c.validPct),f.valid+'개 / '+fmt(f.valid*.5)+'초']));});
const origin=data.provenance??{};txt('referenceState','A 구간 '+(data.references.a?.length??0)+'행 · A 시간 사건 '+(data.references.timingA?.length??0)+'행'+(origin.a?' | 구간 파일: '+origin.a.file+' · '+origin.a.importedAt:'')+(origin.timingA?' | 시간 파일: '+origin.timingA.file:'')+' · 평가자 코드: '+([...new Set([...(data.references.a??[]),...(data.references.timingA??[])].map(r=>r.rater_id||'코드 미제공'))].join(', ')||'자료 없음')+' · 기존 B·협의자료는 A 계산에 사용하지 않습니다.');
$('episodeRows').replaceChildren();for(const c of ['INSIDE','OUTSIDE']){const e=a.episodes[c];tr('episodeRows',[label(c),e.n,fmt(e.durationsSeconds.reduce((s,x)=>s+x,0)),fmt(e.mean,3),fmt(e.median,3),fmt(e.sd,3),fmt(e.min,3),fmt(e.max,3)]);}
$('timingRows').replaceChildren();a.timing.forEach(t=>tr('timingRows',[timeNames[t.kind],t.n,fmt(t.mean,3),fmt(t.median,3),fmt(t.sd,3),fmt(t.min,3),fmt(t.max,3),t.missing+' / '+t.invalid]));
$('programRows').replaceChildren();txt('programState',data.referenceOnly?'A 전용 세션 · 프로그램 관측자료 없음':p.fields.map(f=>metricNames[f.field]+' 측정 실패 '+f.failed+'/'+f.total+' 구간 ('+fmt(f.failurePct)+'%)').join(' · ')+' · 보정 후 완전한 0.5초 구간 요약');
p.fields.forEach(f=>f.categories.forEach(c=>tr('programRows',[metricNames[f.field],label(c.category),c.n,fmt(c.seconds),fmt(c.totalPct),fmt(c.validPct)])));
$('programTimingRows').replaceChildren();p.timing.forEach(t=>tr('programTimingRows',[timeNames[t.kind],t.n,fmt(t.mean,3),fmt(t.median,3),fmt(t.sd,3),fmt(t.min,3),fmt(t.max,3)]));
$('binRows').replaceChildren();const refs=new Map((data.references.a??[]).map(r=>[Number(r.bin_start_s),r]));grid.slice(-100).forEach(b=>{const r=refs.get(b.start);tr('binRows',[fmt(b.start,3),fmt(b.end,3),...['direction','screen','head'].map(f=>r?.[f]?label(r[f]):'미입력')]);});txt('reviewSubject',(data.meta.participantSnapshot?.name??repo?.listProfiles().find(p=>p.id===data.meta.participant)?.name??'기본정보 미등록')+' · '+data.meta.participant);resetInline(data);renderInlineEvents();}

function download(content,name,type){const blob=content instanceof Blob?content:new Blob([content],{type});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/[^a-zA-Z0-9_.-]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function out(rows,suffix){if(selected)download(csv(rows),selected.meta.session+'_'+suffix+'.csv','text/csv;charset=utf-8');}
$('downloadSimple').onclick=()=>{if(selected)download(csv(simpleRows(selected)),selected.meta.session+'_gaze_trials.csv','text/csv;charset=utf-8');};
$('exportFull').onclick=()=>download(JSON.stringify(selected,null,2),selected.meta.session+'_full.json','application/json');
const aColumns=['session_id','participant_id','mode','role','bin_start_s','bin_end_s','direction','screen','head','rater_id','video_offset_s','observation_start_s','observation_end_s','source_file','imported_at'];
const timeColumns=['session_start_s','session_end_s','duration_s','session_id','participant_id','mode','role','id','kind','start_s','end_s','rater_id','time_basis','video_offset_s','source_file','imported_at'];
