try{registry=mountRegistry({repo,getHistory:()=>history,isBusy:()=>running||loading||inlineDirty||readOnlyStorage,prepare:prepareForSubject,openReview:(data,edit)=>{if(inlineDirty&&selected!==data){notice('작성 중인 A 관찰자료를 먼저 저장하세요.',true);return;}selected=data;show('review');$('inlineEditor').open=edit;},notice,download,onRestored:rows=>{history=rows;selected=null;refreshHistory();}});}catch(e){notice('대상자 저장소 확인이 필요합니다: '+e.message,true);}
