for(const [id,field]of [['batchDirection','direction'],['batchScreen','screen'],['batchHead','head']])fillStateSelect($(id),field);
function resetInline(data){if(inlineData===data&&inlineDirty)return;if(inlineData!==data){if(inlineVideoURL)URL.revokeObjectURL(inlineVideoURL);inlineVideoURL=null;$('inlineVideo').pause();$('inlineVideo').removeAttribute('src');$('inlineVideo').load();$('inlineVideo').hidden=true;$('inlineVideoFile').value='';editingEventId=null;lastRemovedEvent=null;$('eventStart').value='';$('eventEnd').value='';}inlineData=data;inlinePage=0;inlineDirty=false;const map=new Map((data.references.a??[]).map(r=>[Number(r.bin_start_s),r]));inlineDraft=referenceBins(data).map(b=>({session_id:data.meta.session,participant_id:data.meta.participant,bin_start_s:b.start,bin_end_s:b.end,direction:'',screen:'',head:'',...map.get(b.start)}));$('inlineRater').value=data.references.a?.find(r=>r.rater_id)?.rater_id||'RATER_A';$('inlineOffset').value=data.video?.startedAtSessionSeconds??data.references.a?.[0]?.video_offset_s??0;$('batchStart').value=inlineDraft[0]?.bin_start_s??0;$('batchEnd').value=inlineDraft.at(-1)?.bin_end_s??0;renderInline();}
function renderInline(){$('inlineRows').replaceChildren();for(const r of inlineDraft.slice(inlinePage*10,inlinePage*10+10)){const row=document.createElement('tr');let c=document.createElement('td');c.textContent=fmt(r.bin_start_s,1)+' – '+fmt(r.bin_end_s,1);row.append(c);c=document.createElement('td');const seek=document.createElement('button');seek.textContent='보기';seek.onclick=()=>{if(!$('inlineVideo').src)return notice('기준영상을 먼저 선택하세요.');$('inlineVideo').pause();$('inlineVideo').currentTime=Math.max(0,r.bin_start_s-Number($('inlineOffset').value));};c.append(seek);row.append(c);for(const f of ['direction','screen','head']){c=document.createElement('td');const select=document.createElement('select');select.setAttribute('aria-label',r.bin_start_s+'초 '+metricNames[f]);fillStateSelect(select,f,r[f]);select.onchange=()=>{r[f]=select.value;inlineDirty=true;txt('inlineFeedback','작성 중 · A 관찰자료 저장을 눌러 반영하세요.');};c.append(select);row.append(c);}$('inlineRows').append(row);}txt('inlinePage',inlineDraft.length?(inlinePage+1)+' / '+Math.ceil(inlineDraft.length/10):'관찰 구간 없음');$('inlinePrev').disabled=!inlinePage;$('inlineNext').disabled=(inlinePage+1)*10>=inlineDraft.length;txt('inlineFeedback',inlineDraft.length+'구간 · '+(inlineDirty?'작성 중 · 저장 필요':'저장된 기록과 연결됨'));}
