function renderInlineEvents(){$('inlineEventList').replaceChildren();for(const e of selected?.references.timingA??[]){const line=document.createElement('div');line.className='inline-event';const text=document.createElement('span');text.textContent=e.id+' · '+timeNames[e.kind]+' · '+e.start_s+' → '+e.end_s+'초 ('+(e.time_basis??'session')+')';const edit=document.createElement('button');edit.textContent='수정';edit.onclick=()=>{editingEventId=e.id;$('eventKind').value=e.kind;const offset=e.time_basis==='video'?Number(e.video_offset_s):0;$('eventStart').value=Number(e.start_s)+offset;$('eventEnd').value=Number(e.end_s)+offset;txt('addInlineEvent','시간 사건 수정 저장');};const remove=document.createElement('button');remove.textContent='삭제';remove.onclick=()=>{lastRemovedEvent={session:selected,row:{...e}};if(editingEventId===e.id){editingEventId=null;$('eventStart').value='';$('eventEnd').value='';txt('addInlineEvent','시간 사건 저장');}selected.references.timingA=selected.references.timingA.filter(r=>r.id!==e.id);save();renderReview(selected);notice('시간 사건을 삭제했습니다. 아래에서 되돌릴 수 있습니다.');};line.append(text,edit,remove);$('inlineEventList').append(line);}if(lastRemovedEvent?.session===selected){const undo=document.createElement('button');undo.textContent='방금 삭제한 사건 되돌리기';undo.onclick=()=>{try{const next=[...selected.references.timingA,lastRemovedEvent.row];validateTimingARows(next,selected);selected.references.timingA=next;lastRemovedEvent=null;save();renderReview(selected);}catch(e){notice('되돌리기 실패: '+e.message,true);}};$('inlineEventList').append(undo);}}
