window.addEventListener('beforeunload',e=>{if(inlineDirty){e.preventDefault();e.returnValue='';}});
$('exportRecovery').hidden=!readOnlyStorage;$('exportRecovery').onclick=()=>download(JSON.stringify({schema:'gaze-storage-recovery-raw',exportedAt:new Date().toISOString(),profiles:storage.getItem('gaze-participants-v1'),sessions:storage.getItem('gaze-validation-v2'),journal:storage.getItem('gaze-participants-transaction-v1')},null,2),'gaze_recovery_raw.json','application/json');mountResearchExports({download,getData:()=>selected});registry?.render();controls();show('subjects');

function renderAutomatic(data,summary){const r=renderResearch(data);renderSimple(data);$('automaticCards').replaceChildren();$('automaticTimes').replaceChildren();if(data.referenceOnly){txt('automaticState','영상 A 관찰용 기록입니다. 자동 측정은 대상자 화면의 새 측정 시작으로 진행하세요.');return;}
const samples=data.samples??[],faces=samples.filter(s=>s.face).length;
if(r.status!=='measured'){txt('automaticState','시선 보정 후 측정 구간이 없어 주시·화면 밖 시간은 아직 산출할 수 없습니다. 관측 프레임 '+samples.length+'개는 기록되어 있습니다.');stat('automaticCards','얼굴 감지',samples.length?fmt(100*faces/samples.length)+'%':'자료 없음',faces+' / '+samples.length+' 관측 프레임');return;}
txt('automaticState',(data.meta.mode==='demo'?'DEMO · 합성자료 | ':'')+(data.calibration?.coordinateSpace==='browser viewport'?'브라우저 표시 영역 기준 | ':'')+'보정 후 '+fmt(r.observedSeconds,3)+'초 관측 · 프레임 시각 기준 · 평가자 A 입력 없이 산출');
for(const [field,title] of [['direction','시선 방향'],['head','머리 방향']]){const f=r.fields.find(x=>x.field===field);stat('automaticCards',title,f.valid+' / '+f.total+'구간','0.5초 구간별 방향과 관측 수 · 아래 원자료에서 확인');}
stat('automaticCards','화면 주시',fmt(r.insideSeconds,3)+'초',r.insideStats.n+'구간 · 평균 '+fmt(r.insideStats.mean,3)+'초');
stat('automaticCards','화면 밖 주시',r.outsideCount+'회 / '+fmt(r.outsideSeconds,3)+'초','실패 구간에서 끊음 · 실패 '+fmt(r.failedSeconds,3)+'초 별도');
for(const [kind,title] of [['RESPONSE','반응시간'],['DELAY','지연시간']]){const t=summary.timing.find(t=>t.kind===kind);stat('automaticCards',title,t?.n?fmt(t.mean,3)+'초':'사건 미기록','수동 시작·종료 사건 기준 · '+(t?.n??0)+'건 · 개별 값은 문항 원자료');}
const faceInfo=document.createElement('p');faceInfo.textContent='얼굴 감지 '+(samples.length?fmt(100*faces/samples.length)+'%':'자료 없음')+' · '+faces+'/'+samples.length+'프레임(보정 포함)';$('automaticTimes').append(faceInfo);
for(const t of summary.timing.filter(t=>t.kind!=='GAZE')){const row=document.createElement('p');row.textContent=timeNames[t.kind]+': '+(t.n?'n='+t.n+' · 평균 '+fmt(t.mean,3)+'초':'사건 미기록 · 문항 시작/응답/지연 버튼으로 수집합니다.');$('automaticTimes').append(row);}}
